let pdfTask = null;
let pdfSession = 0;
let pdfLibrary;

function closePdf(){
  pdfSession++;
  if(pdfTask){ pdfTask.destroy(); pdfTask = null; }
}

async function showPdf(doc){
  const session = pdfSession;
  const status = screen.querySelector('.pdf-status');
  try {
    pdfLibrary ||= import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/legacy/build/pdf.mjs');
    const pdfjs = await pdfLibrary;
    if(session !== pdfSession) return;
    pdfjs.GlobalWorkerOptions.workerSrc = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/legacy/build/pdf.worker.mjs';
    pdfTask = pdfjs.getDocument(new URL(doc.file, location.href).href);
    const pdf = await pdfTask.promise;
    if(session !== pdfSession) return;
    const pages = screen.querySelector('.pdf-pages');
    status.textContent = `Страниц: ${pdf.numPages}`;
    for(let n=1; n<=pdf.numPages; n++){
      const page = await pdf.getPage(n);
      if(session !== pdfSession) return;
      const width = Math.max(280, pages.clientWidth);
      const viewport = page.getViewport({scale: width / page.getViewport({scale:1}).width});
      const canvas = document.createElement('canvas');
      const ratio = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.ceil(viewport.width * ratio);
      canvas.height = Math.ceil(viewport.height * ratio);
      canvas.setAttribute('aria-label', `Страница ${n} из ${pdf.numPages}`);
      canvas.setAttribute('role', 'img');
      pages.append(canvas);
      await page.render({canvasContext:canvas.getContext('2d'), viewport,
        transform:[ratio,0,0,ratio,0,0]}).promise;
      page.cleanup();
    }
  } catch(error){
    if(session !== pdfSession) return;
    status.textContent = 'Не удалось загрузить документ. Проверьте интернет и попробуйте снова.';
    const retry = document.createElement('button');
    retry.className = 'list-item';
    retry.textContent = 'Повторить загрузку';
    retry.addEventListener('click', ()=>render());
    status.after(retry);
  }
}

async function showCostume(item,session){
  const container=screen.querySelector('.costume-detail');
  try{
    const response=await fetch('./'+item.file+'?v=20261020-2');
    if(!response.ok) throw new Error('load');
    const data=await response.json();
    if(session!==costumeSession)return;
    container.replaceChildren();
    const photo=document.createElement('img');
    photo.className='costume-photo';photo.src='./'+data.photo;photo.alt=data.name;
    container.append(photo);
    if(data.description){
      const text=document.createElement('p');text.className='costume-description';text.textContent=data.description;container.append(text);
    }
    if(data.table){
      const table=document.createElement('table');table.className='costume-table';
      data.table.forEach((row,i)=>{const tr=document.createElement('tr');row.forEach(value=>{const td=document.createElement(i===0?'th':'td');td.textContent=value;tr.append(td);});table.append(tr);});
      container.append(table);
    }
  }catch(error){
    if(session!==costumeSession)return;
    container.textContent='Не удалось загрузить карточку. Проверьте интернет.';
    const retry=document.createElement('button');retry.className='list-item';retry.textContent='Повторить';retry.addEventListener('click',()=>render());container.append(retry);
  }
}


function venueFields(container,item){
  container.replaceChildren();
  const address=document.createElement('p');address.className='venue-address';address.textContent=item.address;container.append(address);
  const fields=document.createElement('dl');fields.className='venue-fields';
  for(const [key,label] of [['sound','Звук'],['load','Занос'],['parking','Парковка'],['dressing','Гримёрка']]){
    const row=document.createElement('div');
    const dt=document.createElement('dt');dt.textContent=label;
    const dd=document.createElement('dd');dd.textContent=item[key];
    row.append(dt,dd);fields.append(row);
  }
  container.append(fields);
}

function renderVenues(){
  screen.innerHTML='<div class="list venues-list"></div>';
  const list=screen.querySelector('.venues-list');
  DATA.venues.forEach(v=>{
    const card=document.createElement('article');card.className='list-item venue-card';card.dataset.venueId=v.id;
    const head=document.createElement('div');head.className='venue-heading';
    const icon=document.createElement('div');icon.className='list-icon';icon.textContent='⌂';
    const name=document.createElement('h4');name.textContent=v.name;head.append(icon,name);card.append(head);
    const body=document.createElement('div');body.className='venue-body';
    if(v.halls){
      const label=document.createElement('label');label.className='venue-select-label';label.textContent='Зал';
      const select=document.createElement('select');select.className='venue-select';select.setAttribute('aria-label','Зал — '+v.name);
      v.halls.forEach(h=>{const option=document.createElement('option');option.value=h.id;option.textContent=h.name;select.append(option);});
      select.addEventListener('change',()=>venueFields(body,v.halls.find(h=>h.id===select.value)));
      label.append(select);card.append(label);venueFields(body,v.halls[0]);
    }else venueFields(body,v);
    card.append(body);list.append(card);
  });
}

function searchVenues(query){
  let count=0;
  for(const v of DATA.venues){
    const card=screen.querySelector('[data-venue-id="'+v.id+'"]');
    const candidates=(v.halls||[v]).map(h=>({hall:h,score:query.trim()?searchScore(query,v.name+' '+(v.halls?h.name:''),[h.address,h.sound,h.load,h.parking,h.dressing].join(' ')):1})).sort((a,b)=>b.score-a.score);
    const match=candidates[0];card.hidden=match.score===0;
    if(match.score){
      count++;
      const select=card.querySelector('select');
      if(select){select.value=match.hall.id;venueFields(card.querySelector('.venue-body'),match.hall);}
    }
  }
  screen.querySelector('.search-empty')?.remove();
  if(!count){const empty=document.createElement('div');empty.className='empty search-empty';empty.textContent='Ничего не найдено. Попробуйте другое слово.';empty.setAttribute('role','status');screen.append(empty);}
}

function setHeader(t, s, placeholder='Поиск'){
  title.textContent = t;
  searchInput.placeholder = placeholder;
  backBtn.classList.toggle('hidden', activeRoute === 'access');
}

function listItem(icon, heading, sub, extra=''){
  return `<button class="list-item searchable">
    <div class="list-icon">${icon}</div>
    <div class="list-main"><h4>${heading}</h4><p>${sub}</p>${extra}</div>
    <div class="list-chevron">›</div>
  </button>`;
}

function navigate(route, push=true){
  activeRoute = route;
  if(push && routeStack[routeStack.length-1] !== route) routeStack.push(route);
  render();
  if(!route.startsWith('venue:')) window.scrollTo({top:0, behavior:'smooth'});
}

